Brief: Tell me how MangoDB executes an aggregation pipeline. — about executeStage

1. const stageKeys = Object.keys(stage);
2. if (stageKeys.length !== 1) {
3. throw new Error('Pipeline stage must have exactly one field');
4. const stageKey = stageKeys[0];
5. const stageValue = (stage as unknown as Record<string, unknown>)[stageKey];
6. return this.execMatch(stageValue as Filter<Document>, docs);
7. case '$project':
8. return this.execProject(
9. stageValue as Record<string, 0 | 1 | string | ProjectExpression>,
10. docs
11. case '$sort':
12. return this.execSort(stageValue as SortSpec, docs);

